-- ============================================================================
-- B5 FOLLOW-ON W1, D4 PART C: the open-book label on the welldesign capstone
-- brief.
--
-- WHY. A lesson or a panel's opening view prints the answers these capstones
-- grade (docs/graded-field-audit/README.md finding 3; FOLLOW-ON-PROGRAMME.md
-- section 3). Until W5 re-cases or strips them, the brief says so. The label is
-- the brief's first sentence; the rest of the prompt is unchanged. The same
-- note heads the tier's capstone lesson (NextGen zip).
--
-- beginner: some graded figure(s) printed; section 3 pick B (strip)
-- intermediate: some graded figure(s) printed; section 3 pick B (strip)
-- advanced: some graded figure(s) printed; section 3 pick B (strip)
--
-- THE LABEL:
--   Open book, in part: some of the figures this capstone grades can be read in
--   this tier's lessons or on a panel as it opens, so for now those check that
--   you can find, read and report them correctly. A later update takes them out
--   of the lessons and panels.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its post-20261024a value exactly, before and after, so no answer
-- grades differently and no attempt guard is needed.
--
-- GUARDS. Each prompt must hold its post-20261024a text (md5, rewritten) or
-- its labelled text (left alone). Anything else raises and the file rolls
-- back. Runs after 20261024a_w1_*. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
  v_s2       text;
begin
  -- welldesign / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'welldesign' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w1 open-book welldesign refused: welldesign/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '2d542668d8922a5d989e70fa751efd79' and fields = '[{"key": "ade_mincurve_tvd", "tol": 0.002, "unit": "ft", "label": "ADE chapter 8 minimum-curvature TVD", "expected": 1653.986686265376}, {"key": "ade_tangential_tvd_error", "tol": 0.005, "unit": "ft", "label": "Tangential TVD less published value", "expected": -25.38120586938976}, {"key": "golden_ft_tvd", "tol": 0.005, "unit": "ft", "label": "Feet well TVD at total depth", "expected": 3686.9804661202493}, {"key": "golden_ft_vertical_section", "tol": 0.005, "unit": "ft", "label": "Feet well vertical section", "expected": 1255.8726308373678}, {"key": "golden_m_north", "tol": 0.005, "unit": "m", "label": "Metric well north displacement", "expected": -1320.505235386686}, {"key": "buildhold_end_tvd", "tol": 0.005, "unit": "ft", "label": "Compiled build-and-hold end TVD", "expected": 1481.1257260785915}]'::jsonb then 'old'
              when md5(prompt) = '443db164c59e8310153d45aff2f3b8a1' and fields = '[{"key": "ade_mincurve_tvd", "tol": 0.002, "unit": "ft", "label": "ADE chapter 8 minimum-curvature TVD", "expected": 1653.986686265376}, {"key": "ade_tangential_tvd_error", "tol": 0.005, "unit": "ft", "label": "Tangential TVD less published value", "expected": -25.38120586938976}, {"key": "golden_ft_tvd", "tol": 0.005, "unit": "ft", "label": "Feet well TVD at total depth", "expected": 3686.9804661202493}, {"key": "golden_ft_vertical_section", "tol": 0.005, "unit": "ft", "label": "Feet well vertical section", "expected": 1255.8726308373678}, {"key": "golden_m_north", "tol": 0.005, "unit": "m", "label": "Metric well north displacement", "expected": -1320.505235386686}, {"key": "buildhold_end_tvd", "tol": 0.005, "unit": "ft", "label": "Compiled build-and-hold end TVD", "expected": 1481.1257260785915}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'welldesign' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w1 open-book welldesign refused: welldesign/beginner matches neither its published form (prompt md5 2d542668d8922a5d989e70fa751efd79) nor its W1 form (prompt md5 443db164c59e8310153d45aff2f3b8a1), with the fields this file was generated against';
  end if;

  -- welldesign / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'welldesign' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w1 open-book welldesign refused: welldesign/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '33c2f04817aa14d6078a1fb5dc8f888f' and fields = '[{"key": "well1_cov_nn", "tol": 0.005, "unit": "m2", "label": "North-north covariance entry", "expected": 8547.77693579118}, {"key": "well1_sigma_lateral", "tol": 0.005, "unit": "m", "label": "Lateral one-sigma", "expected": 95.65082424690361}, {"key": "well1_sigma_highside", "tol": 0.005, "unit": "m", "label": "Highside one-sigma", "expected": 21.636241962526093}, {"key": "well1_ellipse95_semimajor", "tol": 0.005, "unit": "m", "label": "Horizontal ellipse semi-major", "expected": 267.39198828526287}, {"key": "well1_ellipse_azimuth_deg", "tol": 0.005, "unit": "deg", "label": "Ellipse major axis azimuth", "expected": 165.05207648844214}, {"key": "well1_amil_share_pct", "tol": 0.005, "unit": "percent", "label": "Largest source share by trace", "expected": 58.294649231431436}]'::jsonb then 'old'
              when md5(prompt) = 'b4ae95ab406b65347940e11361588a3b' and fields = '[{"key": "well1_cov_nn", "tol": 0.005, "unit": "m2", "label": "North-north covariance entry", "expected": 8547.77693579118}, {"key": "well1_sigma_lateral", "tol": 0.005, "unit": "m", "label": "Lateral one-sigma", "expected": 95.65082424690361}, {"key": "well1_sigma_highside", "tol": 0.005, "unit": "m", "label": "Highside one-sigma", "expected": 21.636241962526093}, {"key": "well1_ellipse95_semimajor", "tol": 0.005, "unit": "m", "label": "Horizontal ellipse semi-major", "expected": 267.39198828526287}, {"key": "well1_ellipse_azimuth_deg", "tol": 0.005, "unit": "deg", "label": "Ellipse major axis azimuth", "expected": 165.05207648844214}, {"key": "well1_amil_share_pct", "tol": 0.005, "unit": "percent", "label": "Largest source share by trace", "expected": 58.294649231431436}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'welldesign' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w1 open-book welldesign refused: welldesign/intermediate matches neither its published form (prompt md5 33c2f04817aa14d6078a1fb5dc8f888f) nor its W1 form (prompt md5 b4ae95ab406b65347940e11361588a3b), with the fields this file was generated against';
  end if;

  -- welldesign / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'welldesign' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 open-book welldesign refused: welldesign/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'd83bf1f1b460e034b729b0251b51a08e' and fields = '[{"key": "well01_min_sf", "tol": 0.0005, "unit": "-", "label": "Minimum separation factor, offset 01", "expected": 1.400242036710446}, {"key": "well09_min_sf", "tol": 0.00005, "unit": "-", "label": "Minimum separation factor, offset 09", "expected": 0.009794688844024428}, {"key": "well10_min_sf", "tol": 0.0005, "unit": "-", "label": "Minimum separation factor, offset 10", "expected": -0.6068571428571429}, {"key": "well10_min_sf_at_k5", "tol": 0.0005, "unit": "-", "label": "Offset 10 minimum at k of 5.0", "expected": -0.4248}, {"key": "wmm_max_declination_error_deg", "tol": 0.000005, "unit": "deg", "label": "Worst declination error, 12 points", "expected": 0.00461482429820137}, {"key": "wmm_declination_at_80n_0e", "tol": 0.00005, "unit": "deg", "label": "Declination at 80N 0E, epoch 2025.0", "expected": 1.2814821161348655}]'::jsonb then 'old'
              when md5(prompt) = '58320c07b0166e2c4c46909a2467a2b6' and fields = '[{"key": "well01_min_sf", "tol": 0.0005, "unit": "-", "label": "Minimum separation factor, offset 01", "expected": 1.400242036710446}, {"key": "well09_min_sf", "tol": 0.00005, "unit": "-", "label": "Minimum separation factor, offset 09", "expected": 0.009794688844024428}, {"key": "well10_min_sf", "tol": 0.0005, "unit": "-", "label": "Minimum separation factor, offset 10", "expected": -0.6068571428571429}, {"key": "well10_min_sf_at_k5", "tol": 0.0005, "unit": "-", "label": "Offset 10 minimum at k of 5.0", "expected": -0.4248}, {"key": "wmm_max_declination_error_deg", "tol": 0.000005, "unit": "deg", "label": "Worst declination error, 12 points", "expected": 0.00461482429820137}, {"key": "wmm_declination_at_80n_0e", "tol": 0.00005, "unit": "deg", "label": "Declination at 80N 0E, epoch 2025.0", "expected": 1.2814821161348655}]'::jsonb then 'new'
              else 'other' end
    into v_s2 from public.academy_capstones where app_slug = 'welldesign' and tier = 'advanced' and active;
  if v_s2 = 'other' then
    raise exception 'w1 open-book welldesign refused: welldesign/advanced matches neither its published form (prompt md5 d83bf1f1b460e034b729b0251b51a08e) nor its W1 form (prompt md5 58320c07b0166e2c4c46909a2467a2b6), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' and v_s1 = 'new' and v_s2 = 'new' then
    raise notice 'w1 open-book welldesign: 0 of 3 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 open-book welldesign refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book, in part: some of the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now those check that you can find, read and report them correctly. A later update takes them out of the lessons and panels. Six survey calculations on three fixtures. (1) On the Applied Drilling Engineering chapter 8 survey, compute the full minimum-curvature survey table and report the true vertical depth at the deepest station. (2) On that same survey, compute the tangential method''s true vertical depth, summing over intervals the interval length times the cosine of the inclination at the LOWER station of each interval, and report that value MINUS the published minimum-curvature true vertical depth of 1653.99 ft. The published value is the reference, not the engine''s own answer. (3) On the FEET golden well, report the true vertical depth at total depth. (4) On that same well, report the vertical section at total depth, using the fixture''s own reference azimuth of 75 degrees rather than any default. (5) On the METRIC golden well, using its stated reference azimuth of 200 degrees, report the north displacement at total depth; it is negative. (6) Compile the first published build-and-hold design, kicking off vertical, building at the stated rate to the stated inclination and holding for the stated length on the stated azimuth, and report the true vertical depth at the last row of the compiled table.',
           fields = '[{"key": "ade_mincurve_tvd", "tol": 0.002, "unit": "ft", "label": "ADE chapter 8 minimum-curvature TVD", "expected": 1653.986686265376}, {"key": "ade_tangential_tvd_error", "tol": 0.005, "unit": "ft", "label": "Tangential TVD less published value", "expected": -25.38120586938976}, {"key": "golden_ft_tvd", "tol": 0.005, "unit": "ft", "label": "Feet well TVD at total depth", "expected": 3686.9804661202493}, {"key": "golden_ft_vertical_section", "tol": 0.005, "unit": "ft", "label": "Feet well vertical section", "expected": 1255.8726308373678}, {"key": "golden_m_north", "tol": 0.005, "unit": "m", "label": "Metric well north displacement", "expected": -1320.505235386686}, {"key": "buildhold_end_tvd", "tol": 0.005, "unit": "ft", "label": "Compiled build-and-hold end TVD", "expected": 1481.1257260785915}]'::jsonb
     where app_slug = 'welldesign' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book welldesign refused: welldesign/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '443db164c59e8310153d45aff2f3b8a1' and fields = '[{"key": "ade_mincurve_tvd", "tol": 0.002, "unit": "ft", "label": "ADE chapter 8 minimum-curvature TVD", "expected": 1653.986686265376}, {"key": "ade_tangential_tvd_error", "tol": 0.005, "unit": "ft", "label": "Tangential TVD less published value", "expected": -25.38120586938976}, {"key": "golden_ft_tvd", "tol": 0.005, "unit": "ft", "label": "Feet well TVD at total depth", "expected": 3686.9804661202493}, {"key": "golden_ft_vertical_section", "tol": 0.005, "unit": "ft", "label": "Feet well vertical section", "expected": 1255.8726308373678}, {"key": "golden_m_north", "tol": 0.005, "unit": "m", "label": "Metric well north displacement", "expected": -1320.505235386686}, {"key": "buildhold_end_tvd", "tol": 0.005, "unit": "ft", "label": "Compiled build-and-hold end TVD", "expected": 1481.1257260785915}]'::jsonb) from public.academy_capstones where app_slug = 'welldesign' and tier = 'beginner' and active) is not true then
    raise exception 'w1 open-book welldesign refused: welldesign/beginner does not read back as its W1 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book, in part: some of the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now those check that you can find, read and report them correctly. A later update takes them out of the lessons and panels. Six quantities from ONE station of the ISCWSA MWD Rev4 validation well: the DEEPEST station, index 267 of 268, at 8000 m measured depth. Run the standard MWD Rev4 parameter set with no corrections applied, using the fixture''s own header: total field 50000 nT, dip 72 degrees, declination minus 4 degrees, convergence zero, azimuths referenced to true north, standard gravity, and the vertical inclination limit the fixture states. Report: (1) the north-north entry of the TOTAL covariance, which is a variance in square metres and not a sigma; (2) the LATERAL one-sigma uncertainty in the borehole frame, which needs the rotation from north-east-vertical and is not the east sigma; (3) the HIGHSIDE one-sigma uncertainty in that same frame; (4) the semi-major axis of the HORIZONTAL ellipse, built from the north-east block''s eigen-decomposition, at the two-dimensional 95 percent confidence factor of 2.7955; (5) the azimuth of that ellipse''s major axis in degrees, which does not depend on the confidence factor because scaling an ellipse does not rotate it; and (6) the percentage of the total variance contributed by the single largest source, measured by TRACE, that source''s three variances summed and divided by the same sum over all sources, times a hundred.',
           fields = '[{"key": "well1_cov_nn", "tol": 0.005, "unit": "m2", "label": "North-north covariance entry", "expected": 8547.77693579118}, {"key": "well1_sigma_lateral", "tol": 0.005, "unit": "m", "label": "Lateral one-sigma", "expected": 95.65082424690361}, {"key": "well1_sigma_highside", "tol": 0.005, "unit": "m", "label": "Highside one-sigma", "expected": 21.636241962526093}, {"key": "well1_ellipse95_semimajor", "tol": 0.005, "unit": "m", "label": "Horizontal ellipse semi-major", "expected": 267.39198828526287}, {"key": "well1_ellipse_azimuth_deg", "tol": 0.005, "unit": "deg", "label": "Ellipse major axis azimuth", "expected": 165.05207648844214}, {"key": "well1_amil_share_pct", "tol": 0.005, "unit": "percent", "label": "Largest source share by trace", "expected": 58.294649231431436}]'::jsonb
     where app_slug = 'welldesign' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book welldesign refused: welldesign/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'b4ae95ab406b65347940e11361588a3b' and fields = '[{"key": "well1_cov_nn", "tol": 0.005, "unit": "m2", "label": "North-north covariance entry", "expected": 8547.77693579118}, {"key": "well1_sigma_lateral", "tol": 0.005, "unit": "m", "label": "Lateral one-sigma", "expected": 95.65082424690361}, {"key": "well1_sigma_highside", "tol": 0.005, "unit": "m", "label": "Highside one-sigma", "expected": 21.636241962526093}, {"key": "well1_ellipse95_semimajor", "tol": 0.005, "unit": "m", "label": "Horizontal ellipse semi-major", "expected": 267.39198828526287}, {"key": "well1_ellipse_azimuth_deg", "tol": 0.005, "unit": "deg", "label": "Ellipse major axis azimuth", "expected": 165.05207648844214}, {"key": "well1_amil_share_pct", "tol": 0.005, "unit": "percent", "label": "Largest source share by trace", "expected": 58.294649231431436}]'::jsonb) from public.academy_capstones where app_slug = 'welldesign' and tier = 'intermediate' and active) is not true then
    raise exception 'w1 open-book welldesign refused: welldesign/intermediate does not read back as its W1 form';
  end if;

  if v_s2 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book, in part: some of the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now those check that you can find, read and report them correctly. A later update takes them out of the lessons and panels. Six numbers from the ISCWSA standard clearance set and the geomagnetic model. Use the published clearance parameters throughout: pedal-curve method, confidence factor 3.5, surface position sigma 0.5 m, tool projection allowance 0.3 m, reference hole radius 0.4572 m, offset hole radius 0.3048 m, and the ISCWSA MWD Rev4 error model with each well''s own header from the fixture. Report: (1) the MINIMUM separation factor over the reference well''s stations against offset 01; (2) the same against offset 09, which is very nearly zero; (3) the same against offset 10, the only case with a kickoff, supplying the kickoff depth the fixture states so the shared uncertainty above it is removed; it is NEGATIVE. (4) Rerun case 3 with the confidence factor raised to 5.0 and nothing else changed, and report that minimum. Compute it by rerunning rather than by scaling field 3. (5) Evaluate the WMM2025 model at each of the publisher''s twelve test points and report the LARGEST absolute declination error in degrees, a maximum and not a mean. (6) Report the declination the model gives at 80 degrees north, 0 degrees east, at sea level, at the epoch 2025.0.',
           fields = '[{"key": "well01_min_sf", "tol": 0.0005, "unit": "-", "label": "Minimum separation factor, offset 01", "expected": 1.400242036710446}, {"key": "well09_min_sf", "tol": 0.00005, "unit": "-", "label": "Minimum separation factor, offset 09", "expected": 0.009794688844024428}, {"key": "well10_min_sf", "tol": 0.0005, "unit": "-", "label": "Minimum separation factor, offset 10", "expected": -0.6068571428571429}, {"key": "well10_min_sf_at_k5", "tol": 0.0005, "unit": "-", "label": "Offset 10 minimum at k of 5.0", "expected": -0.4248}, {"key": "wmm_max_declination_error_deg", "tol": 0.000005, "unit": "deg", "label": "Worst declination error, 12 points", "expected": 0.00461482429820137}, {"key": "wmm_declination_at_80n_0e", "tol": 0.00005, "unit": "deg", "label": "Declination at 80N 0E, epoch 2025.0", "expected": 1.2814821161348655}]'::jsonb
     where app_slug = 'welldesign' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book welldesign refused: welldesign/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '58320c07b0166e2c4c46909a2467a2b6' and fields = '[{"key": "well01_min_sf", "tol": 0.0005, "unit": "-", "label": "Minimum separation factor, offset 01", "expected": 1.400242036710446}, {"key": "well09_min_sf", "tol": 0.00005, "unit": "-", "label": "Minimum separation factor, offset 09", "expected": 0.009794688844024428}, {"key": "well10_min_sf", "tol": 0.0005, "unit": "-", "label": "Minimum separation factor, offset 10", "expected": -0.6068571428571429}, {"key": "well10_min_sf_at_k5", "tol": 0.0005, "unit": "-", "label": "Offset 10 minimum at k of 5.0", "expected": -0.4248}, {"key": "wmm_max_declination_error_deg", "tol": 0.000005, "unit": "deg", "label": "Worst declination error, 12 points", "expected": 0.00461482429820137}, {"key": "wmm_declination_at_80n_0e", "tol": 0.00005, "unit": "deg", "label": "Declination at 80N 0E, epoch 2025.0", "expected": 1.2814821161348655}]'::jsonb) from public.academy_capstones where app_slug = 'welldesign' and tier = 'advanced' and active) is not true then
    raise exception 'w1 open-book welldesign refused: welldesign/advanced does not read back as its W1 form';
  end if;

  raise notice 'w1 open-book welldesign: % of 3 row(s) written, % already applied', v_written, 3 - v_written;
end $$;
